<?php
/**
 * Design section blocks.
 *
 * Every section of the design is a block (blocks/blocks.json, generated by
 * tools/build-theme.py). A block type holds the section's markup as a tree
 * whose texts, images, links and lists are fields; a block in a page stores
 * only the field values ("data"). Pages are edited in the block editor:
 * fields in the sidebar, the section previewed in the canvas.
 *
 * Tree nodes:
 *   ['s', text]                         fixed text
 *   ['t', key] / ['r', key]             text field / text with simple HTML
 *   ['l', key, attrs]                   lines field: one <span attrs> per line
 *   ['x', html]                         fixed markup (SVG)
 *   ['c', function, args]               automatic content (news, works, form …)
 *   ['e', tag, attrs, children]         element; an attribute may be ['f', key, link|image|alt|var]
 *   ['rep', key, variants, separator]   list; each item is {_v: variant, …values}
 */

/** Block definitions from blocks/blocks.json. */
function ta_blocks() {
	static $def = null;
	if ( null === $def ) {
		$def = json_decode( (string) file_get_contents( TA_DIR . '/blocks/blocks.json' ), true );
	}
	return $def;
}

add_filter(
	'block_categories_all',
	function ( $categories ) {
		$ours = array();
		foreach ( ta_blocks()['categories'] as $i => $title ) {
			$ours[] = array( 'slug' => 'ta-' . $i, 'title' => 'デザイン｜' . $title );
		}
		$ours[] = array( 'slug' => 'ta-parts', 'title' => 'デザイン｜共通パーツ' );
		return array_merge( $ours, $categories );
	}
);

add_action(
	'init',
	function () {
		$attrs = array( 'data' => array( 'type' => 'object', 'default' => array() ) );
		foreach ( ta_blocks()['types'] as $name => $type ) {
			register_block_type(
				$name,
				array(
					'api_version'     => 3,
					'title'           => $type['title'],
					'attributes'      => $attrs,
					'supports'        => array( 'html' => false, 'className' => false, 'customClassName' => false ),
					'render_callback' => function ( $attributes ) use ( $name ) {
						return ta_render_section( $name, $attributes['data'] ?? array() );
					},
				)
			);
		}
		register_block_type(
			'ta/breadcrumb',
			array(
				'api_version'     => 3,
				'title'           => 'パンくずリスト',
				'attributes'      => $attrs,
				'supports'        => array( 'html' => false, 'className' => false, 'customClassName' => false ),
				'render_callback' => function ( $attributes ) {
					ob_start();
					ta_auto_breadcrumb( $attributes['data']['label'] ?? '' );
					return ob_get_clean();
				},
			)
		);
	}
);

add_action(
	'enqueue_block_editor_assets',
	function () {
		wp_enqueue_script( 'ta-blocks', TA_URI . '/assets/js/blocks.js', array( 'wp-blocks', 'wp-element', 'wp-block-editor', 'wp-components' ), TA_VERSION, true );
		$def = ta_blocks();
		wp_add_inline_script(
			'ta-blocks',
			'window.taBlocks = ' . wp_json_encode(
				array(
					'types'      => $def['types'],
					'categories' => $def['categories'],
					'calls'      => $def['calls'],
					'home'       => home_url( '/' ),
					'img'        => TA_URI . '/assets/img/',
					'pdf'        => ta_pdf_url(),
					'en'         => ta_en_url(),
				)
			) . ';',
			'before'
		);
	}
);

/** HTML of one section block. Values missing from $data fall back to the design. */
function ta_render_section( $name, $data ) {
	$type = ta_blocks()['types'][ $name ] ?? null;
	if ( ! $type ) {
		return '';
	}
	$data = array_merge( $type['defaults'], is_array( $data ) ? $data : array() );
	ob_start();
	ta_render_node( $type['tree'], $data );
	return ob_get_clean();
}

function ta_render_node( $n, $data ) {
	switch ( $n[0] ) {
		case 's':
			echo esc_html( $n[1] );
			break;
		case 't':
			echo esc_html( (string) ( $data[ $n[1] ] ?? '' ) );
			break;
		case 'r':
			echo wp_kses_post( (string) ( $data[ $n[1] ] ?? '' ) );
			break;
		case 'l':
			foreach ( preg_split( '/\r?\n/', (string) ( $data[ $n[1] ] ?? '' ) ) as $line ) {
				if ( '' !== trim( $line ) ) {
					echo '<span' . ta_render_attrs( $n[2], $data ) . '>' . esc_html( $line ) . '</span>';
				}
			}
			break;
		case 'x':
			echo $n[1]; // phpcs:ignore WordPress.Security.EscapeOutput -- fixed SVG from the theme.
			break;
		case 'c':
			ta_render_call( $n[1], $n[2] );
			break;
		case 'e':
			$extra = '';
			if ( 'a' === $n[1] && isset( $n[2]['href'] ) && ! isset( $n[2]['target'] ) ) {
				$href = is_array( $n[2]['href'] ) ? ta_link_url( $data[ $n[2]['href'][1] ] ?? '' ) : $n[2]['href'];
				if ( ta_is_external( $href ) || preg_match( '/\.pdf($|[?#])/i', (string) $href ) ) {
					$extra = ' target="_blank" rel="noopener"';
				}
			}
			echo '<' . $n[1] . ta_render_attrs( $n[2], $data ) . $extra . '>';
			if ( ! in_array( $n[1], array( 'img', 'br', 'input', 'meta', 'hr', 'source' ), true ) ) {
				foreach ( $n[3] as $child ) {
					ta_render_node( $child, $data );
				}
				echo '</' . $n[1] . '>';
			}
			break;
		case 'rep':
			$items = is_array( $data[ $n[1] ] ?? null ) ? $data[ $n[1] ] : array();
			foreach ( array_values( $items ) as $i => $item ) {
				if ( $i ) {
					echo esc_html( $n[3] );
				}
				$variant = $n[2][ (int) ( $item['_v'] ?? 0 ) ] ?? $n[2][0];
				ta_render_node( $variant, is_array( $item ) ? $item : array() );
			}
			break;
	}
}

function ta_render_attrs( $attrs, $data ) {
	$out = '';
	foreach ( $attrs as $name => $value ) {
		if ( is_array( $value ) ) {
			$v = $data[ $value[1] ] ?? '';
			if ( 'link' === $value[2] ) {
				$value = esc_url( ta_link_url( $v ) );
			} elseif ( 'image' === $value[2] ) {
				$value = esc_url( ta_image_url( $v ) );
			} else {
				$value = esc_attr( (string) $v );
			}
		} else {
			$value = esc_attr( $value );
		}
		$out .= ' ' . $name . '="' . $value . '"';
	}
	return $out;
}

/** Link field value → URL. "/path/" is inside the site; @pdf / @en come from Customizer. */
function ta_link_url( $v ) {
	$v = trim( (string) $v );
	if ( '@pdf' === $v ) {
		return ta_pdf_url();
	}
	if ( '@en' === $v ) {
		return ta_en_url();
	}
	if ( '' !== $v && '/' === $v[0] && ( ! isset( $v[1] ) || '/' !== $v[1] ) ) {
		return home_url( $v );
	}
	return $v;
}

/** True for a link to another site (opened in a new tab). */
function ta_is_external( $url ) {
	if ( ! preg_match( '#^(https?:)?//#i', (string) $url ) ) {
		return false;
	}
	$host = wp_parse_url( $url, PHP_URL_HOST );
	return $host && strtolower( $host ) !== strtolower( (string) wp_parse_url( home_url(), PHP_URL_HOST ) );
}

/** Image field value → URL: a media library item, a full URL, or a file bundled with the theme. */
function ta_image_url( $v ) {
	if ( is_array( $v ) ) {
		$url = ! empty( $v['id'] ) ? wp_get_attachment_image_url( (int) $v['id'], 'full' ) : '';
		return $url ? $url : ( $v['url'] ?? '' );
	}
	$v = (string) $v;
	return preg_match( '#^https?://#', $v ) ? $v : TA_URI . '/assets/img/' . $v;
}

/** Automatic content inside a section. */
function ta_render_call( $fn, $args ) {
	switch ( $fn ) {
		case 'ta_news_rows_simple':
			ta_news_rows_simple( (int) $args ?: 3 );
			break;
		case 'ta_news_tabs':
		case 'ta_news_list':
		case 'ta_pagination':
		case 'ta_works_filters':
		case 'ta_works_grid':
			$fn();
			break;
		case 'ta_contact_form':
			get_template_part( 'template-parts/contact-form' );
			break;
	}
}

/** Breadcrumb from the page's position: parents, list pages, then $label (or the title). */
function ta_auto_breadcrumb( $label = '' ) {
	$trail = array();
	if ( is_singular( 'works' ) || is_post_type_archive( 'works' ) ) {
		if ( is_singular() ) {
			$trail[] = array( '実績', get_post_type_archive_link( 'works' ) );
		}
	} elseif ( is_post_type_archive( 'news' ) ) {
		$label = $label ?: 'お知らせ・インサイト';
	} elseif ( is_singular() ) {
		foreach ( array_reverse( get_post_ancestors( get_queried_object_id() ) ) as $ancestor ) {
			$trail[] = array( get_the_title( $ancestor ), get_permalink( $ancestor ) );
		}
	}
	if ( '' === $label ) {
		$label = is_singular() ? get_the_title( get_queried_object_id() ) : wp_strip_all_tags( get_the_archive_title() );
	}
	$trail[] = array( $label, null );
	ta_breadcrumb( $trail );
}

/** True when the content is built from design section blocks. */
function ta_has_sections( $content ) {
	return false !== strpos( (string) $content, '<!-- wp:ta/' );
}

/** Initial content of a designed page (blocks/content/{key}.html), or ''. */
function ta_design_content( $key ) {
	$file = TA_DIR . '/blocks/content/' . $key . '.html';
	return file_exists( $file ) ? (string) file_get_contents( $file ) : '';
}

/**
 * Prints a designed page: its own content when it is built from sections,
 * otherwise the design's initial content for $key.
 */
function ta_render_design( $content, $key ) {
	if ( ! ta_has_sections( $content ) ) {
		$content = ta_design_content( $key );
	}
	echo do_blocks( $content ); // phpcs:ignore WordPress.Security.EscapeOutput -- block output.
}

/**
 * Content holders for pages that are not WordPress pages (/works/, /news/, 404):
 * private pages whose blocks are shown around the automatic lists.
 */
function ta_holders() {
	return array(
		'works' => '【一覧ページ】実績（/works/）',
		'news'  => '【一覧ページ】お知らせ・インサイト（/news/）',
		'404'   => '【404ページ】ページが見つかりません',
	);
}

function ta_holder_content( $key ) {
	$page = get_page_by_path( 'ta-holder-' . $key, OBJECT, array( 'page' ) );
	return $page ? $page->post_content : '';
}
